package io.github.arcadiumclient.runtime.client.optimizations;
import java.util.*;import java.util.function.Consumer;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public final class PreparedPlayerFingerprint073Test {
 static ClassNode synthetic(){ClassNode n=new ClassNode();n.version=Opcodes.V17;n.access=Opcodes.ACC_PUBLIC;n.name="Fixture";n.superName="java/lang/Object";MethodNode m=new MethodNode(Opcodes.ACC_PUBLIC|Opcodes.ACC_STATIC,"method","(I)V",null,null);m.maxLocals=1;m.instructions.add(new LabelNode());m.instructions.add(new InsnNode(Opcodes.RETURN));m.instructions.add(new LabelNode());m.maxStack=0;n.methods.add(m);FieldNode f=new FieldNode(Opcodes.ACC_STATIC|Opcodes.ACC_FINAL,"field","I",null,1);n.fields.add(f);return n;}
 static AnnotationNode merged(String session){AnnotationNode a=new AnnotationNode("Lorg/spongepowered/asm/mixin/transformer/meta/MixinMerged;");a.values=new ArrayList<>(List.of("mixin","FixtureMixin","priority",1000,"sessionId",session));return a;}
 static void annotate(ClassNode n){n.methods.get(0).invisibleAnnotations=new ArrayList<>(List.of(merged("one")));n.fields.get(0).visibleAnnotations=new ArrayList<>(List.of(merged("one")));}
 static void value(AnnotationNode a,String key,Object value){for(int i=0;i<a.values.size();i+=2)if(a.values.get(i).equals(key)){a.values.set(i+1,value);return;}a.values.add(key);a.values.add(value);}
 static byte[] raw(ClassNode n){ClassWriter writer=new ClassWriter(0);n.accept(writer);return writer.toByteArray();}
 static String cf(ClassNode n){return PreparedPlayerFingerprint073.classFingerprint(n);}static String mf(MethodNode m){return PreparedPlayerFingerprint073.methodFingerprint(m);}
 static void rejectClass(Consumer<ClassNode> change){ClassNode n=synthetic();annotate(n);String before=cf(n);change.accept(n);assertNotEquals(before,cf(n));}
 static void rejectMethod(Consumer<MethodNode> change){ClassNode n=synthetic();annotate(n);MethodNode m=n.methods.get(0);String before=mf(m);change.accept(m);assertNotEquals(before,mf(m));}
 @Test void sessionValueChangesOnMethodAndFieldAreAccepted(){ClassNode n=synthetic();annotate(n);String before=cf(n),method=mf(n.methods.get(0));value(n.methods.get(0).invisibleAnnotations.get(0),"sessionId","different-UUID");value(n.fields.get(0).visibleAnnotations.get(0),"sessionId","other-UUID");assertEquals(before,cf(n));assertEquals(method,mf(n.methods.get(0)));}
 @Test void codeOwnerAndInstructionOperandsArePreserved(){rejectMethod(m->m.instructions.insert(new MethodInsnNode(Opcodes.INVOKESTATIC,"ChangedOwner","run","()V",false)));rejectMethod(m->m.instructions.insert(new LdcInsnNode("sessionId-is-executable-here")));}
 @Test void mergedMixinOwnerIsNotIgnored(){rejectClass(n->value(n.fields.get(0).visibleAnnotations.get(0),"mixin","ForeignFieldMixin"));rejectMethod(m->value(m.invisibleAnnotations.get(0),"mixin","ForeignMethodMixin"));}
 @Test void mergedPriorityIsNotIgnored(){rejectClass(n->value(n.fields.get(0).visibleAnnotations.get(0),"priority",999));rejectMethod(m->value(m.invisibleAnnotations.get(0),"priority",1001));}
 @Test void methodDescriptorAccessSignatureAndExceptionsArePreserved(){rejectMethod(m->m.desc="(II)V");rejectMethod(m->m.access|=Opcodes.ACC_SYNCHRONIZED);rejectMethod(m->m.signature="(TI;)V");rejectMethod(m->m.exceptions.add("java/lang/IllegalStateException"));}
 @Test void fieldsNamesDescriptorsAccessValuesAndAdditionsArePreserved(){rejectClass(n->n.fields.get(0).name="changed");rejectClass(n->n.fields.get(0).desc="J");rejectClass(n->n.fields.get(0).access|=Opcodes.ACC_PUBLIC);rejectClass(n->n.fields.get(0).value=2);rejectClass(n->n.fields.add(new FieldNode(Opcodes.ACC_PRIVATE,"additional","J",null,null)));}
 @Test void unrelatedAnnotationSessionKeyIsNotNormalized(){rejectMethod(m->{m.invisibleAnnotations.get(0).desc="Lother/MixinMerged;";});ClassNode n=synthetic();AnnotationNode a=new AnnotationNode("Lother/Annotation;");a.values=new ArrayList<>(List.of("sessionId","one"));n.methods.get(0).visibleAnnotations=new ArrayList<>(List.of(a));String before=mf(n.methods.get(0));value(a,"sessionId","two");assertNotEquals(before,mf(n.methods.get(0)));}
 @Test void caseTypeMissingAndAdditionalKeysAreNotIgnored(){rejectMethod(m->value(m.invisibleAnnotations.get(0),"sessionID","different-case"));rejectMethod(m->value(m.invisibleAnnotations.get(0),"sessionId",7));rejectMethod(m->{m.invisibleAnnotations.get(0).values.remove(5);m.invisibleAnnotations.get(0).values.remove(4);});rejectMethod(m->value(m.invisibleAnnotations.get(0),"newMetadata","new"));}
 @Test void annotationPresenceVisibilityAndWrongTargetArePreserved(){rejectClass(n->n.fields.get(0).visibleAnnotations.clear());rejectMethod(m->{m.visibleAnnotations=m.invisibleAnnotations;m.invisibleAnnotations=null;});ClassNode n=synthetic();n.visibleAnnotations=new ArrayList<>(List.of(merged("one")));String before=cf(n);value(n.visibleAnnotations.get(0),"sessionId","two");assertNotEquals(before,cf(n));}
 @Test void executableUuidStringsAreNotScrubbed(){ClassNode n=synthetic();annotate(n);MethodNode m=n.methods.get(0);LdcInsnNode ldc=new LdcInsnNode("one");m.instructions.insert(ldc);m.maxStack=1;String before=cf(n),method=mf(m);ldc.cst="two";value(m.invisibleAnnotations.get(0),"sessionId","two");assertNotEquals(before,cf(n));assertNotEquals(method,mf(m));}
 @Test void debugPolicyMatchesExistingMethodFingerprintOnly(){ClassNode n=synthetic();MethodNode m=n.methods.get(0);String before=mf(m),clazz=cf(n);LabelNode start=(LabelNode)m.instructions.getFirst(),end=(LabelNode)m.instructions.getLast();m.instructions.insert(start,new FrameNode(Opcodes.F_SAME,0,null,0,null));m.instructions.insert(start,new LineNumberNode(9876,start));m.localVariables=new ArrayList<>(List.of(new LocalVariableNode("debug","I",null,start,end,0)));LocalVariableAnnotationNode annotation=new LocalVariableAnnotationNode(TypeReference.newTypeReference(TypeReference.LOCAL_VARIABLE).getValue(),null,new LabelNode[]{start},new LabelNode[]{end},new int[]{0},"LFixtureDebug;");annotation.values=new ArrayList<>(List.of("value","debug"));m.visibleLocalVariableAnnotations=new ArrayList<>(List.of(annotation));assertEquals(before,mf(m));assertNotEquals(clazz,cf(n));}
 @Test void nonDebugMethodParametersAndLimitsRemainHashed(){rejectMethod(m->m.parameters=new ArrayList<>(List.of(new ParameterNode("namedArgument",0))));rejectMethod(m->m.maxStack++);rejectMethod(m->m.maxLocals++);}
 @Test void freshConstantPoolIgnoresOnlyUnreferencedOldPoolEntries()throws Exception{ClassNode n=synthetic();annotate(n);ClassWriter writer=new ClassWriter(0);writer.newConst("unreferenced-pool-entry-random-session");n.accept(writer);ClassNode reread=new ClassNode();new ClassReader(writer.toByteArray()).accept(reread,0);assertEquals(cf(n),cf(reread));}
 @Test void inputTreesAndAnnotationValuesAreNotMutated(){ClassNode n=synthetic();annotate(n);MethodNode m=n.methods.get(0);byte[] before=raw(n);AbstractInsnNode[] nodes=m.instructions.toArray();Object[] methodValues=m.invisibleAnnotations.get(0).values.toArray(),fieldValues=n.fields.get(0).visibleAnnotations.get(0).values.toArray();cf(n);mf(m);assertArrayEquals(before,raw(n));assertArrayEquals(nodes,m.instructions.toArray());assertArrayEquals(methodValues,m.invisibleAnnotations.get(0).values.toArray());assertArrayEquals(fieldValues,n.fields.get(0).visibleAnnotations.get(0).values.toArray());}
}
